/* Certificate fonts, embedded so the PNG renders the same on every server (no file tracing, no network).
 * Cormorant Garamond + Inter (latin + cyrillic) and Mrs Saint Delafield for the signature — all SIL OFL 1.1, from Fontsource. */

type Weight = 300 | 400 | 500;
export interface CertFont { name: string; data: Buffer; weight: Weight; style: 'normal' | 'italic' }

const RAW: [string, Weight, 'normal' | 'italic', string][] = [
  ['Cormorant', 500, 'normal', ''],
  ['CormorantCyr', 500, 'normal', ''],
  ['Cormorant', 400, 'italic', ''],
  ['CormorantCyr', 400, 'italic', ''],
  ['Inter', 300, 'normal', ''],
  ['InterCyr', 300, 'normal', ''],
  ['Inter', 400, 'normal', ''],
  ['InterCyr', 400, 'normal', ''],
  ['Inter', 500, 'normal', ''],
  ['InterCyr', 500, 'normal', ''],
  ['Signature', 400, 'normal', ''],
];

let cache: CertFont[] | null = null;

export function certificateFonts(): CertFont[] {
  cache ??= RAW.map(([name, weight, style, b64]) => ({ name, weight, style, data: Buffer.from(b64, 'base64') }));
  return cache;
}
